let data = msg.payload;

// Convert string JSON to object
if (typeof data === "string") {
    data = JSON.parse(data);
}

// Match with Python JSON names
let temperature = Number(data.temperature || 0);
let humidity = Number(data.humidity || 0);
let pressure = Number(data.pressure || 0);
let dust = Number(data.dust || 0);
let light = Number(data.light || 0);
let distance = Number(data.distance || 0);
let fan = Number(data.fan_state);

// Occupancy logic
let occupied;

if (distance > 0 && distance <= 100) {
    occupied = "OCCUPIED";
} else {
    occupied = "UNOCCUPIED";
}

// Alert condition for LED
let isAlert = (
    temperature >= 37 ||
    humidity >= 60 ||
    humidity <= 30 ||
    dust >= 55 ||
    pressure >= 1050 ||
    pressure <= 980 ||
    light <= 500
);

// LED Status (TEXT ONLY)
let led;

if (occupied === "UNOCCUPIED") {
    led = "UNOCCUPIED";
}
else if (isAlert) {
    led = "ALERT";
}
else {
    led = "OCCUPIED";
}

// Fan status
let fanStatus;

if (fan === 1) {
    fanStatus = {
        text: "FAN RUNNING",
        color: "#22c55e"
    };
} else {
    fanStatus = {
        text: "FAN OFF",
        color: "#374151"
    };
}

// Alert logic
let alert;

if (temperature >= 37) {
    alert = { text: "HIGH TEMPERATURE", color: "#ef4444" };
}
else if (humidity >= 60) {
    alert = { text: "HIGH HUMIDITY", color: "#f97316" };
}
else if (humidity <= 30) {
    alert = { text: "LOW HUMIDITY", color: "#3b82f6" };
}
else if (dust >= 55) {
    alert = { text: "BAD AIR QUALITY", color: "#eab308" };
}
else if (pressure >= 1050) {
    alert = { text: "HIGH PRESSURE", color: "#8b5cf6" };
}
else if (pressure <= 980) {
    alert = { text: "LOW PRESSURE", color: "#06b6d4" };
}
else {
    alert = { text: "SYSTEM NORMAL", color: "#22c55e" };
}

return [
    { payload: led },
    { payload: temperature },
    { payload: humidity },
    { payload: pressure },
    { payload: dust },
    { payload: light },
    { payload: fanStatus },
    { payload: alert }
];

