// One reading -> Sensor_data view; its trigger splits it into Reading + Reading_Value (values bound as parameters)
let d = msg.payload;
if (typeof d === "string") d = JSON.parse(d);
const num = v => (v === null || v === undefined || v === "" || isNaN(Number(v))) ? null : Number(v);
const fan = Number(d.fan_state) === 1 || String(d.fan_state).toUpperCase() === "ON" ? "ON" : "OFF";
const mode = String(d.mode).toUpperCase() === "AI" ? "AI" : "LOCAL";
msg.topic = "INSERT INTO Sensor_data (Temperature, Humidity, Pressure, Dust, Light, Distance, Fan_Status, Mode) " +
    "VALUES ($t, $h, $p, $d, $l, $dist, $fan, $mode)";
msg.payload = [num(d.temperature), num(d.humidity), num(d.pressure), num(d.dust), num(d.light), num(d.distance), fan, mode];
return msg;

// Step 1: Get data from msg.payload
let rows = msg.payload;

// Step 2: Make sure it is an array
if (!Array.isArray(rows)) {
    rows = [];
}

// Step 3: Limit to last 100 rows only
if (rows.length > 100) {
    rows = rows.slice(rows.length - 100);
}

// Step 4: Prepare empty arrays
let labels = [];       // for time (x-axis)
let tempValues = [];   // for temperature
let humValues = [];    // for humidity
let pressure = [];     // for pressure

// Step 5: Loop through each row
for (let i = 0; i < rows.length; i++) {

    let row = rows[i];

    // Step 6: Timestamp
    let timestamp = row.Timestamp || "";
    let timeOnly = "";

    if (timestamp.includes(" ")) {
        timeOnly = timestamp.split(" ")[1]; // take time part
    }

    // Step 7: Store values
    labels.push(timeOnly);
    tempValues.push(Number(row.Temperature) || 0);
    humValues.push(Number(row.Humidity) || 0);
    pressure.push(Number(row.Pressure) || 0);
}

// Step 8: Create output for Temperature chart
let msg1 = {
    payload: [{
        series: ["Temperature"],
        data: [tempValues],
        labels: labels
    }]
};

// Step 9: Create output for Humidity chart
let msg2 = {
    payload: [{
        series: ["Humidity"],
        data: [humValues],
        labels: labels
    }]
};

// Step 10: Create output for Pressure chart
let msg3 = {
    payload: [{
        series: ["Pressure"],
        data: [pressure],
        labels: labels
    }]
};

// Step 11: Return 3 outputs
return [msg1, msg2, msg3];

const d = typeof msg.payload === 'string' ? JSON.parse(msg.payload) : msg.payload;
msg.payload = JSON.stringify({type: msg.topic.endsWith('/ai') ? 'ai' : 'sensor', data: d});
return msg;

const p = String(msg.payload).trim().toUpperCase();
if (!['AUTO', 'ON', 'OFF'].includes(p) && !/^ACK:(TEMPERATURE|HUMIDITY|PRESSURE|DUST|LIGHT)$/.test(p)) return null;
msg.payload = p;
return msg;

const ev = typeof msg.payload === 'string' ? JSON.parse(msg.payload) : msg.payload;
if (!Array.isArray(ev)) return null;
const tag = m => (String(m).match(/temperature|humidity|pressure|dust|light|distance/i) || [''])[0];
return [ev.map(e => ({topic: 'INSERT INTO AI_Events (Type, Sensor_ID, Message) VALUES ($type, ' +
    '(SELECT Sensor_ID FROM Sensor WHERE Name = $sensor COLLATE NOCASE), $msg)',
    payload: [String(e[0]).slice(0, 16), tag(e[1]), String(e[1]).slice(0, 255)]}))];
